<?php
declare(strict_types=1);
require_once '../config/config.php';
require_once '../includes/church-book-functions.php';
requireLogin();cb_require_permission('wedding_vows.view');$conn->set_charset('utf8mb4');cb_load_dompdf();
use Dompdf\Dompdf;use Dompdf\Options;
$q=cb_clean($_GET['q']??'');$status=cb_clean($_GET['status']??'');$ceremony=cb_clean($_GET['ceremony']??'');$from=cb_clean($_GET['from']??'');$to=cb_clean($_GET['to']??'');$where=['1=1'];$types='';$params=[];
if($q!==''){$where[]="(groom_name LIKE ? OR bride_name LIKE ? OR register_no LIKE ? OR certificate_no LIKE ? OR officiant LIKE ? OR venue LIKE ?)";$like="%{$q}%";for($i=0;$i<6;$i++){$params[]=$like;$types.='s';}}
if(in_array($status,['Scheduled','Banns','Solemnized','Postponed','Cancelled'],true)){$where[]='status=?';$params[]=$status;$types.='s';}
if(in_array($ceremony,['Banns','Licence','Special Licence','Other'],true)){$where[]='ceremony_type=?';$params[]=$ceremony;$types.='s';}
if($from!==''&&cb_valid_date($from)){$where[]='wedding_date>=?';$params[]=$from;$types.='s';}if($to!==''&&cb_valid_date($to)){$where[]='wedding_date<=?';$params[]=$to;$types.='s';}
$rows=cb_fetch_all($conn,"SELECT * FROM wedding_vows WHERE ".implode(' AND ',$where)." ORDER BY wedding_date ASC,id ASC",$types,$params);$site=cb_site_setting($conn,'site_name','Church Management System');
$filter=[];if($q!=='')$filter[]='Search: '.$q;if($status!=='')$filter[]='Status: '.$status;if($ceremony!=='')$filter[]='Basis: '.$ceremony;if($from!=='')$filter[]='From: '.$from;if($to!=='')$filter[]='To: '.$to;$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$html='<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:24px 22px}body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:8px}h1,h2,p{text-align:center;margin:0}h2{font-size:15px}h1{font-size:20px;margin-top:4px}.meta{margin:10px 0 12px;padding:7px 9px;background:#f3f6f8;border:1px solid #d9e0e5}.count{float:right}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #aeb7c0;padding:5px 4px;vertical-align:top;word-wrap:break-word}th{background:#e9eff2;font-size:7px;text-transform:uppercase}.small{font-size:7px;color:#55606d}.footer{margin-top:10px;text-align:right;font-size:7px;color:#667085}</style></head><body>';
$html.='<h2>'.$e($site).'</h2><h1>Wedding Vows Book</h1><p class="small">Generated '.date('d M Y, H:i').'</p><div class="meta">'.($filter?$e(implode(' | ',$filter)):'All wedding records').'<span class="count">Records: '.count($rows).'</span></div>';
$html.='<table><thead><tr><th style="width:3%">#</th><th style="width:8%">Reg. No.</th><th style="width:8%">Date</th><th style="width:13%">Groom</th><th style="width:13%">Bride</th><th style="width:10%">Banns / Licence</th><th style="width:14%">Witnesses</th><th style="width:11%">Officiant</th><th style="width:10%">Certificate</th><th style="width:10%">Status</th></tr></thead><tbody>';
if(!$rows)$html.='<tr><td colspan="10" style="text-align:center">No wedding records found.</td></tr>';
foreach($rows as $i=>$r){$g='<strong>'.$e($r['groom_name']).'</strong>';if(!empty($r['groom_phone']))$g.='<br><span class="small">'.$e($r['groom_phone']).'</span>';$b='<strong>'.$e($r['bride_name']).'</strong>';if(!empty($r['bride_phone']))$b.='<br><span class="small">'.$e($r['bride_phone']).'</span>';$basis=$e($r['ceremony_type']);if(!empty($r['marriage_licence_no']))$basis.='<br><span class="small">'.$e($r['marriage_licence_no']).'</span>';$wit=$e($r['witness_1']?:'-');if(!empty($r['witness_2']))$wit.='<br>'.$e($r['witness_2']);$html.='<tr><td>'.($i+1).'</td><td>'.$e($r['register_no']?:'-').'</td><td>'.$e(date('d M Y',strtotime($r['wedding_date']))).'</td><td>'.$g.'</td><td>'.$b.'</td><td>'.$basis.'</td><td>'.$wit.'</td><td>'.$e($r['officiant']?:'-').'</td><td>'.$e($r['certificate_no']?:'-').'</td><td>'.$e($r['status']).'</td></tr>';}
$html.='</tbody></table><div class="footer">'.$e($site).' · Wedding Vows Book</div></body></html>';
$options=new Options();$options->set('isHtml5ParserEnabled',true);$options->set('defaultFont','DejaVu Sans');$pdf=new Dompdf($options);$pdf->loadHtml($html,'UTF-8');$pdf->setPaper('A4','landscape');$pdf->render();$pdf->stream('wedding-vows-'.date('Y-m-d').'.pdf',['Attachment'=>true]);exit;
